const $=s=>document.querySelector(s);let file=null,urls=[],partLinks=[],joinFiles=[];const drop=$('#dropzone'),input=$('#fileInput'),panel=$('#filePanel'),progress=$('#progressPanel');const fmt=n=>{const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return`${n>=10||i===0?n.toFixed(0):n.toFixed(1)} ${u[i]}`};
function recommend(n){if(n<=500*1048576)return 50;if(n<=2*1073741824)return 200;if(n<=10*1073741824)return 500;return 1024}function update(){if(!file)return;let size=Math.max(1,+$('#partSize').value||1)*+$('#unit').value,count=Math.ceil(file.size/size);$('#partsCount').textContent=`${count} ${count===1?'parte':'partes'}`;$('#recommendation').textContent=count>500?'Considere partes maiores':count===1?'O arquivo já cabe em uma parte':'Divisão pronta para executar'}
function choose(f){if(!f)return;file=f;drop.hidden=true;panel.hidden=false;progress.hidden=true;$('#fileName').textContent=f.name;$('#fileSize').textContent=fmt(f.size);$('#fileExt').textContent=(f.name.split('.').pop()||'FILE').slice(0,5).toUpperCase();$('#partSize').value=recommend(f.size);$('#unit').value='1048576';update()}drop.onclick=()=>input.click();drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click()}};input.onchange=()=>choose(input.files[0]);['dragenter','dragover'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>choose(e.dataTransfer.files[0]));$('#partSize').oninput=update;$('#unit').onchange=update;$('#removeBtn').onclick=()=>{file=null;input.value='';drop.hidden=false;panel.hidden=true;progress.hidden=true;urls.forEach(URL.revokeObjectURL);urls=[]};
function result(name,blob,isPart=true){let url=URL.createObjectURL(blob);urls.push(url);let row=document.createElement('div'),link=document.createElement('a');row.className='result';link.download=name;link.href=url;link.textContent='BAIXAR';row.innerHTML=`<span>${name} · ${fmt(blob.size)}</span>`;row.append(link);$('#results').append(row);if(isPart)partLinks.push(link)}const tick=()=>new Promise(r=>setTimeout(r,20));
$('#splitBtn').onclick=async()=>{if(!file)return;urls.forEach(URL.revokeObjectURL);urls=[];partLinks=[];$('#results').innerHTML='';$('#batchBtn').hidden=true;panel.hidden=true;progress.hidden=false;let bytes=Math.max(1,+$('#partSize').value||1)*+$('#unit').value,count=Math.ceil(file.size/bytes),pad=Math.max(3,String(count).length),base=file.name;for(let i=0;i<count;i++){let name=`${base}.part${String(i+1).padStart(pad,'0')}`;result(name,file.slice(i*bytes,Math.min((i+1)*bytes,file.size)));let pct=Math.round((i+1)/count*100);$('#progressBar').style.width=pct+'%';$('#progressPct').textContent=pct+'%';$('#progressTitle').textContent=`Parte ${i+1} de ${count} pronta`;await tick()}let guide=`SplitX manifest v2\nOriginal: ${file.name}\nSize: ${file.size} bytes\nParts: ${count}\n\nReconstrua em SplitX > Juntar partes.\nWindows: copy /b \"${base}.part*\" \"${base}\"\nmacOS/Linux: cat \"${base}.part\"* > \"${base}\"\n`;result(`${base}.splitx.txt`,new Blob([guide],{type:'text/plain'}),false);$('#progressTitle').textContent='Divisão concluída';$('#progressText').textContent='Baixe todas as partes e mantenha os nomes originais.';$('#batchBtn').hidden=false};$('#batchBtn').onclick=async()=>{for(const link of partLinks){link.click();await new Promise(r=>setTimeout(r,350))}};
function setMode(mode){let split=mode==='split';$('#splitMode').hidden=!split;$('#joinMode').hidden=split;$('#splitTab').classList.toggle('active',split);$('#joinTab').classList.toggle('active',!split)}$('#splitTab').onclick=()=>setMode('split');$('#joinTab').onclick=()=>setMode('join');const joinDrop=$('#joinDrop'),partsInput=$('#partsInput');joinDrop.onclick=()=>partsInput.click();joinDrop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();partsInput.click()}};['dragenter','dragover'].forEach(x=>joinDrop.addEventListener(x,e=>{e.preventDefault();joinDrop.classList.add('drag')}));['dragleave','drop'].forEach(x=>joinDrop.addEventListener(x,e=>{e.preventDefault();joinDrop.classList.remove('drag')}));joinDrop.addEventListener('drop',e=>loadParts(e.dataTransfer.files));partsInput.onchange=()=>loadParts(partsInput.files);function partNumber(name){let m=name.match(/\.part(\d+)$/i);return m?+m[1]:-1}
function loadParts(list){joinFiles=[...list].filter(f=>partNumber(f.name)>0).sort((a,b)=>partNumber(a.name)-partNumber(b.name));if(!joinFiles.length)return;let base=joinFiles[0].name.replace(/\.part\d+$/i,''),total=joinFiles.reduce((n,f)=>n+f.size,0),nums=joinFiles.map(f=>partNumber(f.name));$('#joinName').textContent=base;$('#joinCount').textContent=`${joinFiles.length} partes`;$('#joinSize').textContent=fmt(total);$('#sequence').innerHTML=joinFiles.map(f=>`<span>${String(partNumber(f.name)).padStart(3,'0')}</span>`).join('');let missing=[];for(let i=1;i<=nums.at(-1);i++)if(!nums.includes(i))missing.push(i);$('#joinWarning').textContent=missing.length?`Faltam as partes: ${missing.join(', ')}.`:'Sequência completa e ordenada. Pronta para reconstruir.';$('#joinBtn').disabled=!!missing.length;joinDrop.hidden=true;$('#joinPanel').hidden=false}$('#clearJoin').onclick=()=>{joinFiles=[];partsInput.value='';joinDrop.hidden=false;$('#joinPanel').hidden=true};
$('#joinBtn').onclick=async()=>{if(!joinFiles.length)return;let name=joinFiles[0].name.replace(/\.part\d+$/i,''),label=$('#joinBtn span');label.textContent='Reconstruindo…';try{if('showSaveFilePicker'in window){let handle=await showSaveFilePicker({suggestedName:name}),w=await handle.createWritable();for(let i=0;i<joinFiles.length;i++){await w.write(joinFiles[i]);label.textContent=`Gravando ${i+1} de ${joinFiles.length}…`}await w.close()}else{let total=joinFiles.reduce((n,f)=>n+f.size,0);if(total>1073741824)throw Error('limit');let url=URL.createObjectURL(new Blob(joinFiles)),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}label.textContent='Arquivo reconstruído com sucesso ✓'}catch(e){label.textContent=e.name==='AbortError'?'Reconstrução cancelada':'Use Chrome ou Edge no computador para juntar acima de 1 GB'}setTimeout(()=>label.textContent='Reconstruir arquivo original',4000)};const dialog=$('#infoDialog');$('#howBtn').onclick=()=>dialog.showModal();$('#closeDialog').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};
